import re

# 输入获取
ops = input().split()


# 算法入口
def getResult(ops):
    # ans用于保存每轮的得分
    ans = []

    # 改正则用于判断op是否为一个整数，包括负数
    pattern = r"^\-?\d+$"

    for op in ops:
        # 如果op是整数，则表示本轮得分，直接加入ans
        if re.match(pattern, op):
            ans.append(int(op))
        else:
            # 如果op是+，则表示本轮得分是前两轮得分之和，注意越界处理
            if op == "+":
                if len(ans) < 2:
                    return -1
                else:
                    ans.append(ans[-1] + ans[-2])
            # 如果op是D，表示本轮得分是前一轮得分的双倍，注意越界处理
            elif op == "D":
                if len(ans) < 1:
                    return -1
                else:
                    ans.append(ans[-1] * 2)
            # 如果op是C，则表示本轮无得分，且上一轮得分无效，需要去除
            elif op == "C":
                if len(ans) < 1:
                    return -1
                else:
                    ans.pop()
            else:
                return -1

    ans.append(0)

    return sum(ans)


# 调用算法
print(getResult(ops))
